-- Cadastral Parcels Schema and Seed Data for QadamKadastr (Taitobe / Qosshy)
CREATE TABLE IF NOT EXISTS parcels (
    id SERIAL PRIMARY KEY,
    cadastral_number VARCHAR(50) UNIQUE NOT NULL,
    address_kz TEXT NOT NULL,
    address_ru TEXT NOT NULL,
    area VARCHAR(50) NOT NULL,
    purpose_kz TEXT NOT NULL,
    purpose_ru TEXT NOT NULL,
    status_kz VARCHAR(50) NOT NULL,
    status_ru VARCHAR(50) NOT NULL,
    coordinates JSONB NOT NULL
);

ON CONFLICT (cadastral_number) DO NOTHING;
